{
  "characterization": [
    {
      "id": "K1",
      "text": "Governance is the set of formal and informal arrangements that settle conflicts among parties in a firm, including owner–manager and controlling–minority shareholder conflicts.",
      "passages": ["W1910832905_p01", "W1910832905_p02"]
    },
    {
      "id": "K2",
      "text": "Governance depends on national context: the principal–agent model fits developed economies with efficient contract enforcement, while no single agency model covers all countries.",
      "passages": ["W1910832905_p01"]
    },
    {
      "id": "K3",
      "text": "Governance in emerging economies is produced by costly contract enforcement, which leads to concentrated ownership and, with weak external mechanisms, more conflicts between controlling and minority shareholders.",
      "passages": ["W1910832905_p01", "W1910832905_p02", "W1910832905_p04"]
    },
    {
      "id": "K4",
      "text": "Governance in emerging economies rests on weak formal rules and enforcement, so informal ties such as family, business groups and government contacts carry more of the load.",
      "passages": ["W1910832905_p03"]
    },
    {
      "id": "K5",
      "text": "Governance structures in emerging economies resemble developed-economy ones in form, with shareholders, boards and professional managers, but differ in substance, as founding families keep control informally.",
      "passages": ["W1910832905_p03", "W1910832905_p04"]
    },
    {
      "id": "K6",
      "text": "Governance works as an interdependent bundle of mechanisms, such as boards, ownership concentration, pay and market pressures, that substitute for or complement one another depending on industry, size and country.",
      "passages": ["W1910832905_p05", "W1910832905_p06", "W1910832905_p07"]
    },
    {
      "id": "K7",
      "text": "Governance serves as a barometer of whether national institutions converge toward the Anglo-American model or stay embedded in local banking, labour, tax and competition law.",
      "passages": ["W1910832905_p08"]
    }
  ],
  "stance": {
    "label": "modify",
    "target": "The dominant principal–agent model of corporate governance, based on developed economies",
    "text": "The document keeps the agency view of governance but argues it must be changed for emerging economies, adding controller–minority conflicts and informal institutions.",
    "passages": ["W1910832905_p01", "W1910832905_p02", "W1910832905_p03"]
  }
}

{
  "characterization": [
    {
      "id": "K1",
      "text": "Governance is the discrete contractual or organizational structure (market, bilateral, unified, or internal) within which a transaction is carried out.",
      "passages": ["W1972698480_p01", "W1972698480_p06"]
    },
    {
      "id": "K2",
      "text": "Governance structures include internal arrangements such as job ladders, grievance procedures, pay scales, and collective bargaining, which are more elaborate as human asset specificity rises.",
      "passages": ["W1972698480_p07"]
    },
    {
      "id": "K3",
      "text": "Governance is chosen to match transaction attributes, chiefly asset specificity (site, physical, human), with frequency and uncertainty also mattering, and shifts from markets toward internal organization as specificity rises.",
      "passages": ["W1972698480_p02", "W1972698480_p04", "W1972698480_p06"]
    },
    {
      "id": "K4",
      "text": "Governance operates by economizing on transaction costs, and structures that economize better eventually displace worse ones, ceteris paribus.",
      "passages": ["W1972698480_p01", "W1972698480_p08"]
    },
    {
      "id": "K5",
      "text": "Governance takes the transaction as its unit of analysis, and structural alternatives are compared discretely rather than through marginal calculation.",
      "passages": ["W1972698480_p01", "W1972698480_p08"]
    },
    {
      "id": "K6",
      "text": "Governance problems inside the firm arise only with transaction-specific human assets, not with general skills, even deepened ones.",
      "passages": ["W1972698480_p05"]
    },
    {
      "id": "K7",
      "text": "Governance, such as common ownership of site-specific stations, reflects transaction-cost-economizing judgments and not technological determination.",
      "passages": ["W1972698480_p03"]
    }
  ],
