{
  "characterization": [
    {
      "id": "K1",
      "text": "Governance is a set of structures, namely markets, hierarchies and mixed modes, that can be compared and matched to transactions by efficiency.",
      "passages": ["W1983272981_p04", "W1983272981_p06"]
    },
    {
      "id": "K2",
      "text": "Governance of a cooperative interorganizational relationship emerges, evolves and dissolves over time rather than being fixed at the outset.",
      "passages": ["W1983272981_p01", "W1983272981_p03", "W1983272981_p08"]
    },
    {
      "id": "K3",
      "text": "Governance is produced through formal, legal and informal social-psychological processes of negotiation, commitment and execution among the parties.",
      "passages": ["W1983272981_p01", "W1983272981_p03", "W1983272981_p08"]
    },
    {
      "id": "K4",
      "text": "Governance includes trust, equity and conflict-resolution procedures, which under uncertainty, complexity and long duration can govern better than hierarchical monitoring and control.",
      "passages": ["W1983272981_p08"]
    },
    {
      "id": "K5",
      "text": "Formal safeguards and interpersonal trust within governance interact and can work against each other, so escalating legal structure can wear away trust and end the relationship.",
      "passages": ["W1983272981_p07"]
    },
    {
      "id": "K6",
      "text": "Governance operates at the level of the relationship between organizations, and also applies to relations between units within a firm.",
      "passages": ["W1983272981_p01", "W1983272981_p08"]
    }
  ],
  "stance": {
    "label": "extend",
    "target": "Transaction cost and agency theory accounts of governance as efficient structural choice among markets, hierarchies and hybrids",
    "text": "The document keeps the structural, efficiency-based view of governance and adds a developmental, social-psychological process view of how governance emerges, evolves and dissolves.",
    "passages": ["W1983272981_p04", "W1983272981_p06", "W1983272981_p07", "W1983272981_p08"]
  }
}

