{
  "characterization": [
    {
      "id": "K1",
      "text": "Governance is a control mechanism, the safeguard structure, intended to produce perceptions of fairness or equity in exchange between firms.",
      "passages": ["W2124687760_p02"]
    },
    {
      "id": "K2",
      "text": "Governance consists of a mix of safeguards: legal contracts, self-enforcing trust and reputation, and hostages, used alone or in combination.",
      "passages": ["W2124687760_p02", "W2124687760_p04", "W2124687760_p07"]
    },
    {
      "id": "K3",
      "text": "Governance includes an up-front set-up investment that creates the safeguard and shapes later ongoing bargaining and monitoring costs.",
      "passages": ["W2124687760_p03"]
    },
    {
      "id": "K4",
      "text": "Governance works by changing ongoing transaction costs and value, even when the asset specificity of the exchange stays constant.",
      "passages": ["W2124687760_p02", "W2124687760_p04"]
    },
    {
      "id": "K5",
      "text": "Governance operates through information sharing, repeated exchange and cospecialized investment, which cut information asymmetry and opportunism and raise specialized investment.",
      "passages": ["W2124687760_p06", "W2124687760_p07"]
    },
    {
      "id": "K6",
      "text": "Governance operates at the level of the interfirm exchange relationship, such as automaker-supplier ties, and is distinct from the surrounding institutional environment.",
      "passages": ["W2124687760_p05"]
    }
  ],
  "stance": {
    "label": "modify",
    "target": "Transaction cost economics, in which transaction costs rise with asset specificity",
    "text": "The document adopts the transaction cost framework but changes a core element: costs do not rise with specificity, and governance choice shapes them.",
    "passages": ["W2124687760_p01", "W2124687760_p02", "W2124687760_p04"]
  }
}

